// pick by person dialog
function pickByPerson(name) {
	var dialogClass = window.GlideModal ? GlideModal : GlideDialogWindow;
	var d = new dialogClass('task_assignment_group_dialog');
	d.setTitle('${JS:gs.getMessage("Choose Name, then Group")}');
	d.setFocus('search');
	d.render();
}
